def protectedBinding (setup : Setup baseSpec KemSK) (created : PqxdhRegistrationJointServerBirth.ClientCreated Unit) :
    Word32 × Std.U64 :=
  (PqxdhRootTableInitialization.rootArray created.publicIdentity.ed25519, setup.serverKeyId)

exact_definitions.PqxdhDeploymentServerAuthEmbed.freezeImp:
def freezeImpl {κ : Type} {spec : OracleSpec κ} (dflt : (query : spec.Domain) → spec.Range query)
    (stop : List ((query : spec.Domain) × spec.Range query) → Prop) [DecidablePred stop] :
    QueryImpl spec (StateT (List ((query : spec.Domain) × spec.Range query)) (OracleComp spec)) := fun query journal =>
  if stop journal then pure (dflt query, journal)
  else (fun reply => (reply, journal ++ [⟨query, reply⟩])) <$> (spec.query query : OracleComp spec _)

exact_definitions.PqxdhDeploymentServerAuthEmbed.freeze:
def freeze {κ : Type} {spec : OracleSpec κ} (dflt : (query : spec.Domain) → spec.Range query)
    (stop : List ((query : spec.Domain) × spec.Range query) → Prop) [DecidablePred stop] {α : Type}
    (program : OracleComp spec α) : OracleComp spec (α × List ((query : spec.Domain) × spec.Range query)) :=
  (simulateQ (freezeImpl dflt stop) program).run []

exact_definitions.PqxdhDeploymentServerAuthEmbed.localRoot:
def localRoot (setup : Setup baseSpec KemSK) (input : pqxdh.RootKeyInput) : OracleComp ServerAuthSpec (Option Word32) :=
  (fun prk => some (PqxdhRootTableInitialization.rootArray (expandRoot setup.hmac prk))) <$>
    forward (.hmac zeroSalt (absBytes input.bytes))

exact_definitions.PqxdhDeploymentServerAuth.PinnedMatch:
def PinnedMatch (crypto : Pqxdh.Crypto) (codec : Codec Reader Response) (owner : Nat)
    (pin : PqxdhBeaconPhase2Preparation.Word32) (before : List Reg) (raw : Pqxdh.Bytes) : Prop :=
  ∃ session, PinnedMatchAt crypto codec owner session pin before raw

exact_definitions.PqxdhDeploymentServerAuthBills.coinCap:
def coinCap (caps : KemCaps) (bounds : FreshBounds) (budget : Budget) : Nat :=
  (budget.coin + budget.test + budget.freshBytes bounds) + (64 + caps.keygenCost) * budget.create + 32 * budget.bundle +
    69 * caps.decapsCost * budget.finish

exact_definitions.PqxdhDeploymentServerAuthInjective.Colli:
def Collision (joint : Primitives) (seeds : List IdentitySeed) : Prop :=
  ∃ first second : Nat, first ≠ second ∧ ∃ left right, seeds[first]? = some left ∧ seeds[second]? = some right ∧
    (joint.publicKeys left).ed25519 = (joint.publicKeys right).ed25519
